const CANCELLED = new Set([
  'auth/popup-closed-by-user',
  'auth/cancelled-popup-request',
  'auth/user-cancelled',
]);

/** The sign-in error of a device that is offline - the one worth retrying. */
const NETWORK_ERROR = 'auth/network-request-failed';

