import { AchievementId, isAchievementId } from './achievement-ids';
import { BOT_DIFFICULTIES, BotDifficulty } from '../match/bot-controller';
import { isColonyColor } from './colony-colors';
import { addAttempt, DailyRecord } from '../levels/daily';
import { isInteger, isObject } from '../is-object';
import { LEVELS } from '../levels/levels';
import { betterMedal, MatchRecord, MEDAL_TIERS, MedalTier } from './medallions';
import { isMissionId, MissionId } from '../levels/training-levels';

/** What a player has done over all their matches. */
export interface LifetimeTotals {
  /** Matches against the computer played to the end. */
  matches: number;
  /** Matches against the computer won. */
  wins: number;
  /** Enemy bacteria captured in matches against the computer. */
  captured: number;
  /** Enemy bacteria the walls crushed in matches against the computer. */
  enemyCrushed: number;
  /** Pellets eaten up in matches against the computer. */
  pellets: number;
  /** Matches between two players played to the end. */
  couchMatches: number;
  /**
   * The XP the matches were worth on their own - finishing, winning, the
   * difficulty. The rest of the XP follows from what is held (xp.ts).
   */
  matchXp: number;
}

/** What the game remembers of a player's matches. */
export interface Progress {
  /** The best medallion by level id, then by difficulty. */
  medals: Record<string, Partial<Record<BotDifficulty, MedalTier>>>;
  totals: LifetimeTotals;
  /** The day each achievement was earned, as an ISO date. */
  achievements: Partial<Record<AchievementId, string>>;
  /**
   * Matches between two players won, by the colour of the winning colony -
   * the rivalry on this device, "Orange leads 14 : 9".
   */
  couchWins: Partial<Record<string, number>>;
  /** The daily level: the last day played, its attempts and the streak. */
  daily: DailyRecord | null;
  /** The most levels beaten in one endless run. */
  endlessBest: number;
  /** The day each training mission was done, as an ISO date. */
  training: Partial<Record<MissionId, string>>;
}

export const NO_TOTALS: LifetimeTotals = {
  matches: 0,
  wins: 0,
  captured: 0,
  enemyCrushed: 0,
  pellets: 0,
  couchMatches: 0,
  matchXp: 0,
};

const TOTAL_KEYS = Object.keys(NO_TOTALS) as (keyof LifetimeTotals)[];

export const EMPTY_PROGRESS: Progress = {
  medals: {},
  totals: NO_TOTALS,
  achievements: {},
  couchWins: {},
  daily: null,
  endlessBest: 0,
  training: {},
};

/**
 * How many medallions of each tier are held, over the levels and the
 * difficulties of the game - a level the stored progress knows but the game
 * no longer has does not count.
 */
export function medalTally(
  medals: Progress['medals']
): Record<MedalTier, number> {
import { english, GameText } from '../../i18n/game-text';
import { ACHIEVEMENT_IDS } from './achievement-ids';
import { BOT_DIFFICULTIES, BotDifficulty } from '../match/bot-controller';
import { isLadderLevel, LEVELS } from '../levels/levels';
import { MatchRecord, medalText, MedalTier } from './medallions';
import { bestMedal, Progress } from './progress';
import { missionsDone } from '../levels/training';

/**
 * XP is not stored as such: it follows from the progress. What a match is
 * worth on its own - finishing, winning, the difficulty - is counted as it
 * is played (`totals.matchXp`); what the player holds - the best medallion
 * of each level and difficulty, every achievement, every training mission
 * done - is worth its XP as long as it is held. So XP merges as cleanly as
 * the progress does, never pays the same thing twice, and players who held
 * medallions before XP existed have theirs from the start.
 */

/** One line of what a match earned in XP, for the result screen. */
export interface XpPart {
  label: string;
  /** The label as a text to translate. */
  text?: GameText;
  xp: number;
}

/** What a match earned in XP, line by line. */
export interface XpGain {
  parts: readonly XpPart[];
  total: number;
}

/** XP for playing a match to the end, won or lost. */
const FINISH_XP = 20;
/** XP on top for winning against the computer. */
const WIN_XP = 80;
/** How much the computer's difficulty multiplies finishing and winning. */
const DIFFICULTY_FACTOR: Record<BotDifficulty, number> = {
  easy: 1,
  normal: 1.25,
  hard: 1.5,
};
/** XP a held medallion is worth - a better one replaces the one below. */
export const MEDAL_XP: Readonly<Record<MedalTier, number>> = {
  bronze: 20,
  silver: 40,
  gold: 70,
  platinum: 120,
};
/** XP an achievement is worth. */
export const ACHIEVEMENT_XP = 50;
/** XP a training mission done is worth. */
const MISSION_XP = 25;
/** XP for a match between two players. */
export const COUCH_XP = 15;

/**
 * The match an XP gain is for: one against the computer, one between two
 * players, or a training mission's, which is worth no XP on its own.
 */
export type XpMatch = MatchRecord | 'couch' | 'training';

/** What a match against the computer is worth on its own. */
export function matchXp(
  record: Pick<MatchRecord, 'won' | 'difficulty'>
): number {
  return Math.round(
    (FINISH_XP + (record.won ? WIN_XP : 0)) *
      DIFFICULTY_FACTOR[record.difficulty]
  );
}

/** The XP a player's progress is worth. */
export function xpOf(progress: Progress): number {
  let xp = progress.totals.matchXp;
  for (const { id: levelId } of LEVELS) {
    for (const { id: difficulty } of BOT_DIFFICULTIES) {
      const medal = bestMedal(progress, levelId, difficulty);
      xp += medal === null ? 0 : MEDAL_XP[medal];
    }
